import re
from typing import Optional

# Regular expression for ISO 8601 duration with only weeks, days, hours, minutes, seconds
# Components may be missing; a 'T' introduces time components.
# The last component may contain a decimal fraction.
_DURATION_RE = re.compile(
    r"""
    ^
    P
    (?:
        (?P<weeks>\d+)[W]               # weeks
        |
        (?P<days>\d+)[D]                # days
    )?
    (?:T
        (?:
            (?P<hours>\d+)[H]           # hours
            |
            (?P<minutes>\d+)[M]         # minutes
            |
            (?P<seconds>\d+(\.|,)\d+)[S]   # seconds with fraction
        )?
        (?:\s*
            (?:                          # optional other time components
                (?P<hours2>\d+)[H]|
                (?P<minutes2>\d+)[M]|
                (?P<seconds2>\d+(\.|,)\d+)[S]
            )*
        )
    )?
    $
    """,
    re.VERBOSE | re.IGNORECASE
)

def _parse_number(value: str, allow_fraction: bool) -> float:
    """Parse a numeric string, optionally allowing a decimal fraction."""
    if allow_fraction:
        # replace comma with dot for decimal
        value = value.replace(',', '.')
        try:
            return float(value)
        except ValueError:
            raise ValueError(f"Invalid number: {value}")
    else:
        try:
            return float(int(value))  # ensure no fraction
        except ValueError:
            raise ValueError(f"Invalid integer: {value}")

def parse_duration(text: str) -> float:
    """
    Convert an ISO 8601 duration string to a number of seconds.

    Only weeks, days, hours, minutes and seconds are allowed.  Years and months
    (and any other unexpected component) raise ValueError.
    """
    m = _DURATION_RE.fullmatch(text.strip())
    if not m:
        raise ValueError(f"Invalid ISO 8601 duration: {text!r}")

    # Determine which components are present
    weeks = m.group('weeks')
    days = m.group('days')
    hours = m.group('hours')
    minutes = m.group('minutes')
    seconds = m.group('seconds')

    # Collect all component groups in order
    parts = []
    if weeks:
        parts.append(('weeks', weeks, False))
    if days:
        parts.append(('days', days, False))
    if hours:
        parts.append(('hours', hours, False))
    if minutes:
        parts.append(('minutes', minutes, False))
    if seconds:
        parts.append(('seconds', seconds, True))

    # Ensure at least one component
    if not parts:
        raise ValueError("Duration must contain at least one component")

    # Validate that only the last component may contain a fraction
    for i, (name, value, allow_frac) in enumerate(parts):
        if not allow_frac and ('.' in value or ',' in value):
            raise ValueError(f"Component {name} cannot contain a fraction: {value!r}")

    # Convert to seconds
    total_seconds = 0.0
    for name, value, _ in parts:
        if name == 'weeks':
            total_seconds += _parse_number(value, False) * 7 * 86400
        elif name == 'days':
            total_seconds += _parse_number(value, False) * 86400
        elif name == 'hours':
            total_seconds += _parse_number(value, False) * 3600
        elif name == 'minutes':
            total_seconds += _parse_number(value, False) * 60
        elif name == 'seconds':
            total_seconds += _parse_number(value, True)
    return total_seconds
